MODULE_SOURCE='\nfrom dataclasses import dataclass, asdict\nfrom pathlib import Path\nfrom datetime import datetime, timezone\nimport ast\nimport importlib\nimport inspect\nimport json\n\nfrom qseries_v2.oracle_source_network.runtime.exact_sports_runtime_callable_bindings import load_bindings\n\nADMITTED = ("NFL","NCAAF","NBA","NHL","MLS","EPL")\nPRODUCTION_SURFACE_TESTS = {\n    "NHL": "test_osn_051_nhl_official_json_event_surface_physical_gate.py",\n    "MLS": "test_osn_052_mls_official_stats_exact_query_event_surface_REPAIR.py",\n    "EPL": "test_osn_053_epl_official_json_event_surface_physical_gate.py",\n}\nSTATE_REL = "qseries_v2/oracle_source_network/state/exact_sports_production_event_surfaces.json"\n\n@dataclass(frozen=True)\nclass ProductionSurfaceBinding:\n    league: str\n    module: str\n    function: str\n    required: tuple\n    optional: tuple\n    source_test: str\n    canonical_events_observed: int\n    execution_authority: bool = False\n\n@dataclass(frozen=True)\nclass DirectCycleResult:\n    league: str\n    callables_attempted: tuple\n    canonical_events: tuple\n    event_count: int\n    authority: str\n    execution_authority: bool = False\n\ndef _is_event_object(x):\n    if x is None or isinstance(x,(str,bytes,bytearray,dict,list,tuple)):\n        return False\n    names=set(dir(x))\n    return (\n        "provider_event_id" in names\n        and bool({"home","home_team"} & names)\n        and bool({"away","away_team"} & names)\n        and bool({"scheduled_start","start"} & names)\n    )\n\ndef _find_events(value, depth=0):\n    if depth > 8 or value is None:\n        return ()\n    if _is_event_object(value):\n        return (value,)\n    if isinstance(value,(list,tuple,set)):\n        out=[]\n        for x in value:\n            out.extend(_find_events(x,depth+1))\n        return tuple(out)\n    if isinstance(value,dict):\n        out=[]\n        for x in value.values():\n            out.extend(_find_events(x,depth+1))\n        return tuple(out)\n    for attr in ("events","games","fixtures","matches","rows","data","result","schedule"):\n        if hasattr(value,attr):\n            got=_find_events(getattr(value,attr),depth+1)\n            if got:\n                return got\n    return ()\n\ndef _signature(fn):\n    sig=inspect.signature(fn)\n    req=[]\n    opt=[]\n    for p in sig.parameters.values():\n        if p.kind in (p.VAR_POSITIONAL,p.VAR_KEYWORD):\n            continue\n        if p.default is inspect._empty:\n            req.append(p.name)\n        else:\n            opt.append(p.name)\n    return tuple(req),tuple(opt)\n\ndef _call_zero_or_timeout(fn, required, optional, timeout):\n    if required:\n        raise RuntimeError("required arguments present")\n    kwargs={}\n    if "timeout" in optional:\n        kwargs["timeout"]=timeout\n    return fn(**kwargs)\n\ndef _called_imports_from_test(path):\n    tree=ast.parse(path.read_text(encoding="utf-8"),filename=str(path))\n    imported={}\n    for node in ast.walk(tree):\n        if isinstance(node,ast.ImportFrom) and node.module and node.module.startswith("qseries_v2.oracle_source_network"):\n            for alias in node.names:\n                imported[alias.asname or alias.name]=(node.module,alias.name)\n    calls=[]\n    for node in ast.walk(tree):\n        if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):\n            name=node.func.id\n            if name in imported:\n                mod,fn=imported[name]\n                calls.append((getattr(node,"lineno",999999),mod,fn))\n    calls.sort()\n    seen=set()\n    out=[]\n    for line,mod,fn in calls:\n        key=(mod,fn)\n        if key in seen:\n            continue\n        seen.add(key)\n        out.append((line,mod,fn))\n    return out\n\ndef freeze_production_event_surfaces(root=None, timeout=15):\n    base=Path(root or Path.cwd()).resolve()\n    frozen=[]\n    diagnostics={}\n\n    for league,test_name in PRODUCTION_SURFACE_TESTS.items():\n        test_path=base/test_name\n        if not test_path.exists():\n            raise RuntimeError(f"{league} certified production test missing: {test_name}")\n\n        candidates=_called_imports_from_test(test_path)\n        diagnostics[league]=[]\n        winner=None\n\n        for line,mod,fn_name in candidates:\n            try:\n                obj=getattr(importlib.import_module(mod),fn_name)\n                if not callable(obj):\n                    continue\n                req,opt=_signature(obj)\n            except Exception as exc:\n                diagnostics[league].append({\n                    "module":mod,"function":fn_name,\n                    "state":"IMPORT_OR_SIGNATURE_FAILED",\n                    "error":f"{type(exc).__name__}:{exc}",\n                })\n                continue\n\n            if req:\n                diagnostics[league].append({\n                    "module":mod,"function":fn_name,\n                    "required":req,"optional":opt,\n                    "state":"SKIPPED_REQUIRES_ARGUMENTS",\n                })\n                continue\n\n            try:\n                value=_call_zero_or_timeout(obj,req,opt,timeout)\n                events=_find_events(value)\n            except Exception as exc:\n                diagnostics[league].append({\n                    "module":mod,"function":fn_name,\n                    "required":req,"optional":opt,\n                    "state":"DIRECT_CALL_FAILED",\n                    "error":f"{type(exc).__name__}:{exc}",\n                })\n                continue\n\n            diagnostics[league].append({\n                "module":mod,"function":fn_name,\n                "required":req,"optional":opt,\n                "state":"DIRECT_CALL_OK",\n                "canonical_events":len(events),\n            })\n\n            if events:\n                winner=ProductionSurfaceBinding(\n                    league=league,\n                    module=mod,\n                    function=fn_name,\n                    required=req,\n                    optional=opt,\n                    source_test=test_name,\n                    canonical_events_observed=len(events),\n                )\n                break\n\n        if winner is None:\n            raise RuntimeError(\n                f"{league} certified test exposes no directly callable zero-arg/timeout "\n                f"production function returning canonical events; diagnostics={diagnostics[league]}"\n            )\n        frozen.append(winner)\n\n    state=base/STATE_REL\n    state.parent.mkdir(parents=True,exist_ok=True)\n    state.write_text(json.dumps({\n        "bindings":[asdict(x) for x in frozen],\n        "diagnostics":diagnostics,\n        "authority":"CERTIFIED_PRODUCTION_TEST_IMPORT_CALL_GRAPH",\n        "execution_authority":False,\n    },indent=2,sort_keys=True),encoding="utf-8")\n    return tuple(frozen),state\n\ndef load_production_event_surfaces(root=None):\n    base=Path(root or Path.cwd()).resolve()\n    p=base/STATE_REL\n    return json.loads(p.read_text(encoding="utf-8"))\n\ndef _text_payload(value):\n    if isinstance(value,(str,bytes,bytearray)):\n        return value\n    if isinstance(value,dict):\n        for key in ("body","raw","html","text","content","payload"):\n            v=value.get(key)\n            if isinstance(v,(str,bytes,bytearray)):\n                return v\n    for attr in ("body","raw","html","text","content","payload"):\n        if hasattr(value,attr):\n            v=getattr(value,attr)\n            if isinstance(v,(str,bytes,bytearray)):\n                return v\n    raise RuntimeError(f"no exact text payload found in acquisition return type={type(value).__name__}")\n\ndef _call(fn, required, optional, payload, league, timeout):\n    kwargs={}\n    if "timeout" in optional:\n        kwargs["timeout"]=timeout\n    if "observed_at" in optional:\n        kwargs["observed_at"]=datetime.now(timezone.utc).isoformat()\n    if not required:\n        return fn(**kwargs)\n\n    args=[]\n    for name in required:\n        if name in ("body","raw","payload","html","text","data","document"):\n            args.append(payload)\n        elif name=="league":\n            args.append(league)\n        elif name=="provider":\n            args.append("nba_official" if league=="NBA" else league.lower()+"_official")\n        else:\n            raise RuntimeError(f"unsupported required argument {name!r} for {fn.__module__}:{fn.__name__}")\n    return fn(*args,**kwargs)\n\ndef _legacy_direct_chain(league, root, timeout):\n    data=load_bindings(root=root)\n    rows=[r for r in data["bindings"] if r["league"]==league]\n    acquisition=[r for r in rows if r["function"].startswith("acquire_")]\n    extractors=[r for r in rows if not r["function"].startswith("acquire_")]\n\n    if len(acquisition)!=1 or not extractors:\n        raise RuntimeError(f"{league} exact source/extractor chain incomplete")\n\n    acq=acquisition[0]\n    afn=getattr(importlib.import_module(acq["module"]),acq["function"])\n    attempted=[acq["module"]+":"+acq["function"]]\n    raw=_call(afn,tuple(acq["required"]),tuple(acq["optional"]),None,league,timeout)\n    payload=_text_payload(raw)\n\n    errors=[]\n    for ext in extractors:\n        efn=getattr(importlib.import_module(ext["module"]),ext["function"])\n        attempted.append(ext["module"]+":"+ext["function"])\n        try:\n            value=_call(\n                efn,tuple(ext["required"]),tuple(ext["optional"]),\n                payload,league,timeout\n            )\n            events=_find_events(value)\n        except Exception as exc:\n            errors.append(f"{ext[\'function\']}:{type(exc).__name__}:{exc}")\n            continue\n        if events:\n            return DirectCycleResult(\n                league=league,\n                callables_attempted=tuple(attempted),\n                canonical_events=tuple(events),\n                event_count=len(events),\n                authority="OSN076_EXACT_SOURCE_PLUS_EXTRACTOR",\n            )\n\n    raise RuntimeError(\n        f"{league} exact source/extractor chain produced zero canonical events; errors={errors}"\n    )\n\ndef _production_surface_chain(league, root, timeout):\n    data=load_production_event_surfaces(root=root)\n    rows=[r for r in data["bindings"] if r["league"]==league]\n    if len(rows)!=1:\n        raise RuntimeError(f"{league} expected one frozen production event surface, found {len(rows)}")\n    r=rows[0]\n    fn=getattr(importlib.import_module(r["module"]),r["function"])\n    value=_call_zero_or_timeout(fn,tuple(r["required"]),tuple(r["optional"]),timeout)\n    events=_find_events(value)\n    if not events:\n        raise RuntimeError(\n            f"{league} frozen production surface no longer returns canonical events: "\n            f"{r[\'module\']}:{r[\'function\']}"\n        )\n    return DirectCycleResult(\n        league=league,\n        callables_attempted=(r["module"]+":"+r["function"],),\n        canonical_events=tuple(events),\n        event_count=len(events),\n        authority="OSN051_052_053_CERTIFIED_PRODUCTION_EVENT_SURFACE",\n    )\n\ndef acquire_canonical_events(league, root=None, timeout=12):\n    base=Path(root or Path.cwd()).resolve()\n    if league in ("NFL","NCAAF","NBA"):\n        return _legacy_direct_chain(league,base,timeout)\n    if league in ("NHL","MLS","EPL"):\n        return _production_surface_chain(league,base,timeout)\n    raise RuntimeError(f"league not admitted to production cycle: {league}")\n'
TEST_SOURCE='\nfrom pathlib import Path\nimport json\nfrom qseries_v2.oracle_source_network.runtime.direct_canonical_sports_cycle import (\n    freeze_production_event_surfaces,\n    acquire_canonical_events,\n)\n\nroot=Path.cwd()\n\nbindings,state=freeze_production_event_surfaces(root=root,timeout=15)\nprint("[PRODUCTION_SURFACE_STATE]",state)\nfor b in bindings:\n    print(\n        f"[PRODUCTION_SURFACE] {b.league} "\n        f"{b.module}:{b.function} "\n        f"events={b.canonical_events_observed} "\n        f"source_test={b.source_test}"\n    )\n\nassert tuple(x.league for x in bindings)==("NHL","MLS","EPL")\nassert all(x.canonical_events_observed > 0 for x in bindings)\nassert all(x.execution_authority is False for x in bindings)\n\nrows=[]\nfor league in ("NFL","NCAAF","NBA","NHL","MLS","EPL"):\n    r=acquire_canonical_events(league,root=root,timeout=15)\n    print(\n        f"[DIRECT] {league} events={r.event_count} "\n        f"authority={r.authority}"\n    )\n    for c in r.callables_attempted:\n        print("  [CALL]",c)\n    sample=r.canonical_events[0]\n    print(\n        f"  [SAMPLE] provider_event_id={getattr(sample,\'provider_event_id\',None)} "\n        f"home={getattr(sample,\'home\',getattr(sample,\'home_team\',None))} "\n        f"away={getattr(sample,\'away\',getattr(sample,\'away_team\',None))}"\n    )\n    assert r.event_count > 0\n    assert r.execution_authority is False\n    rows.append({\n        "league":league,\n        "event_count":r.event_count,\n        "authority":r.authority,\n        "callables":list(r.callables_attempted),\n    })\n\nreport=root/"qseries_v2/oracle_source_network/state/osn077_direct_canonical_cycle.json"\nreport.write_text(json.dumps({\n    "rows":rows,\n    "production_surface_authority":True,\n    "execution_authority":False,\n},indent=2),encoding="utf-8")\n\nprint("[REPORT]",report)\nprint("[PASS] NHL/MLS/EPL exact production surfaces frozen from their certified tests")\nprint("[PASS] frozen production surfaces directly returned canonical sports events")\nprint("[PASS] NFL/NCAAF/NBA exact source+extractor chains retained")\nprint("[PASS] no guessed NHL/MLS/EPL schema conversion remains")\nprint("[PASS] no certification subprocess used by production runtime")\nprint("[PASS] OSN-077 production-surface-authority rebuild certified")\n'

